            break                      # torn write: no newline yet
        line = data[offset:end].decode(errors="replace")
        crc, _, body = line.partition("\t")
        if crc != f"{zlib.crc32(body.encode()):08x}":
            break                      # damaged record: stop trusting the log here
        key = body.split("\t", 1)[0]
        index[key] = (offset, end + 1 - offset)
        offset = end + 1
    return index, offset

