def recalc(formulas, values, changed):
    deps = {c: refs(f) for c, f in formulas.items()}
    todo = dependents(deps, changed) | {changed}
    count = 0
    for c in topo_order(deps):
        if c in todo:
            values[c] = evaluate(formulas[c], values)
            count += 1
    return values, count

def evaluate_sum(formula, values):
    m = re.fullmatch(r"=SUM\((\w+:\w+)\)", formula.strip(), re.IGNORECASE)
    return sum(values.get(c, 0) for c in expand_range(m.group(1)))

def topo_order(deps):
    order, done = [], set()
    def visit(c):
        if c in done:
            return
        done.add(c)
        for d in deps.get(c, []):
            visit(d)
        order.append(c)
    for c in deps:
        visit(c)
    return order

