def levels(rules):
    memo = {}
    def level(t):
        if t not in memo:
            memo[t] = 1 + max((level(i) for i in rules[t] if i in rules), default=-1)
        return memo[t]
    out = []
    for t in rules:
        lv = level(t)
        while len(out) <= lv:
            out.append([])
        out[lv].append(t)
    return [sorted(l) for l in out]

