def expand(line, env):
    out, i, quote = [], 0, False
    while i < len(line):
        ch = line[i]
        if ch == "'":
            quote = not quote
            out.append(ch)
            i += 1
        elif ch == "$" and not quote:
            if line[i + 1:i + 2] == "{":
                end = line.index("}", i)
                out.append(env.get(line[i + 2:end], ""))
                i = end + 1
            else:
                j = i + 1
                while j < len(line) and (line[j].isalnum() or line[j] == "_"):
                    j += 1
                out.append(env.get(line[i + 1:j], "") if j > i + 1 else "$")
                i = j
        else:
            out.append(ch)
            i += 1
    return "".join(out)

